def challenge_code(payload, duo=False):
    """Return the 3 button numbers the device waits for in CHALLENGE_CODE mode.

    payload is the exact request bytes the device hashes (all chunks concatenated;
    label32||ct_X for derived X-Wing decaps; label32||ct_X or the input pubkey for
    FIDO2 derives). Digit i = sha256(payload)[index_i] % modulus + 1."""
    h = hashlib.sha256(bytes(payload)).digest()
    mod = CHALLENGE_MODULUS_DUO if duo else CHALLENGE_MODULUS
    return tuple(h[i] % mod + 1 for i in CHALLENGE_INDICES)


def challenge_code_str(payload, duo=False):
    return ' '.join(str(b) for b in challenge_code(payload, duo))


