def classify_response(raw):
    """Classify a raw device report.

    Returns ('error', text) for an Error/ERROR string, ('status', text) for a
    Successfully/UNLOCKED string, otherwise ('data', bytes). The firmware reports
    status and failures as ASCII on the same channel as binary data, so hosts
    must classify, never measure."""
    b = bytes(raw)
    for p in ERROR_PREFIXES:
        if b.startswith(p.encode()):
            return 'error', b.rstrip(b'\x00').decode('ascii', 'replace')
    for p in SUCCESS_PREFIXES:
        if b.startswith(p.encode()):
            return 'status', b.rstrip(b'\x00').decode('ascii', 'replace')
    return 'data', b


def is_error(raw):
    return classify_response(raw)[0] == 'error'


# Derived keys over raw HID (slot 128): [cmd][slot][len|0xFF][keytype][label32][ct_X32?]
