def derived_recipient_payload(key_type, label32):
    """Payload for the OKGETPUBKEY derived-recipient request (one chunk)."""
    label32 = bytes(label32)
    if len(label32) != 32:
        raise ValueError('label32 must be 32 bytes')
    return bytes([int(key_type) & 0x0F]) + label32


def derived_decaps_payload(key_type, label32, ct_x):
    """Payload for the OKDECRYPT derived-decaps request; also what the challenge code hashes."""
    label32, ct_x = bytes(label32), bytes(ct_x)
    if len(label32) != 32 or len(ct_x) != 32:
        raise ValueError('label32 and ct_x must be 32 bytes each')
    return bytes([int(key_type) & 0x0F]) + label32 + ct_x


CAPABILITIES_MAGIC = 202
CAPABILITIES_SELECTOR = b'c'  # OKGETLABELS buffer[5]

class CapabilityFlag(IntEnum):
    NO_PRESS_ALLOWED = 1
    DEBUG_BUILD = 2
    DUO = 4
    PQC = 8
    HKDF_V2_DERIVATION = 16


def parse_capabilities(report):
    """Parse the 64-byte capabilities report. Returns None if it is not one
    (older firmware answers OKGETLABELS 'c' with slot labels instead)."""
    b = bytes(report)
    if len(b) < 64 or b[0] != CAPABILITIES_MAGIC:
        return None
    out = {}
    out['protocol_version'] = b[1]
    out['fw_major'] = b[2]
    out['fw_minor'] = b[3]
    out['fw_patch'] = b[4]
    mask = int.from_bytes(b[5:7], 'little')
    out['key_types'] = [kt for kt in KeyType if mask & (1 << int(kt))]
    out['flags'] = [fl for fl in CapabilityFlag if b[7] & int(fl)]
    out['version'] = b[8:64].split(b'\x00', 1)[0].decode('ascii', 'replace')
    out['user_input_modes'] = {
        f.name: [m for m in UserInputMode
                 if m != UserInputMode.NO_PRESS or f not in NO_PRESS_GATED_FIELDS
                 or CapabilityFlag.NO_PRESS_ALLOWED in out['flags']]
        for f in USER_INPUT_MODE_FIELDS
    }
    return out

